from taf.ue.cus.cus_executor import CusExecutor


EXECUTOR_COMMANDS = ['cm connect', 'cm disconnect', 'version', 'config update',
                     'config remote update', 'config remote reload']

class cus(object):
    ROBOT_LIBRARY_SCOPE = 'GLOBAL'
    ROBOT_LISTENER_API_VERSION = 3

    def __init__(self, store_events=False):
        self._cus_exe = CusExecutor(store_events=store_events)

    def _close(self):
        self._cus_exe.__exit__()

    def get_keyword_names(self):
        keyword_names = [method for method in dir(self) if
                         method[0] != '_' and 'ROBOT' not in method]
        keyword_names.remove('get_keyword_names')
        keyword_names.extend(EXECUTOR_COMMANDS)
        return keyword_names

    def __getattr__(self, command):
        command = command.strip()
        if command in EXECUTOR_COMMANDS:
            return lambda: self._cus_exe.execute_command(command)
        else:
            raise AttributeError()

    def execute_command(self, command):
        """
        Execute a command on the CUS Executor.
        If the command times out on the first attempt, the method retries the execution after handling
        the timeout scenario.

        Args:
            cmd (str): The command to be executed on the executor node.

        Returns:
            list[str]: The result of the command execution as a list of strings.
        """
        return self._cus_exe.execute_command(command)

    def start_live_events(self):
        """
        Start receiving live events from the CUS Executor.
        """
        self._cus_exe.set_store_events(True)

    def stop_live_events(self):
        """
        Stop receiving live events from the CUS Executor.
        """
        self._cus_exe.set_store_events(False)

    def get_live_events(self):
        """
        Get the live events received from the CUS Executor.

        Returns:
            list[str]: The list of live events received.
        """
        return self._cus_exe.get_stored_events()

    def get_and_stop_live_events(self):
        """
        Get the live events and stop receiving them.

        Returns:
            list[str]: The list of live events received.
        """
        self._cus_exe.set_store_events(False)
        return self._cus_exe.get_stored_events()
